// ---- .NET safety net: paste into Build Commit, just before `if (!tree.length)` ----
// Expects: `tree` (array of { path, mode, type, content }) and `root` (project slug).
function dotnetSafetyNet(tree, root) {
  const P = `projects/${root}/`;
  const rel = t => t.path.slice(P.length);
  const has = p => tree.some(t => t.path === P + p);
  const put = (p, content) => {
    const i = tree.findIndex(t => t.path === P + p);
    const entry = { path: P + p, mode: '100644', type: 'blob', content };
    if (i >= 0) tree[i] = entry; else tree.push(entry);
  };
  const add = (p, content) => { if (!has(p)) put(p, content); };

  const m = tree.map(t => rel(t).match(/^src\/([A-Za-z0-9_.]+?)\.(Api|Application|Domain|Infrastructure|Web)\//)).find(Boolean);
  if (!m) return; // no .NET code in this run
  const proj = m[1];
  const W = `src/${proj}.Web/`;
  const appCsproj = `src/${proj}.Application/${proj}.Application.csproj`;

  // namespaces from Domain + Application so Razor pages can see DTOs, interfaces, services
  const ns = new Set();
  tree.forEach(t => {
    const r = rel(t);
    if ((r.startsWith(`src/${proj}.Application/`) || r.startsWith(`src/${proj}.Domain/`)) && r.endsWith('.cs')) {
      const n = String(t.content).match(/^\s*namespace\s+([\w.]+)/m);
      if (n) ns.add(n[1]);
    }
  });

  // --- Web project skeleton (only files the AI did not write) ---
  add(`${W}${proj}.Web.csproj`, `<Project Sdk="Microsoft.NET.Sdk.Web">
  <PropertyGroup>
    <TargetFramework>net8.0</TargetFramework>
    <Nullable>enable</Nullable>
    <ImplicitUsings>enable</ImplicitUsings>
    <RootNamespace>${proj}.Web</RootNamespace>
  </PropertyGroup>
${has(appCsproj) ? `  <ItemGroup>
    <ProjectReference Include="..\\${proj}.Application\\${proj}.Application.csproj" />
  </ItemGroup>
` : ''}</Project>
`);
  add(`${W}Program.cs`, `using ${proj}.Web.Components;

var builder = WebApplication.CreateBuilder(args);
builder.Services.AddRazorComponents().AddInteractiveServerComponents();
builder.Services.AddHttpClient("Api", c => c.BaseAddress = new Uri(builder.Configuration["ApiBaseUrl"] ?? "https://localhost:7001"));
// TODO: register the Api client services used by the pages (e.g. builder.Services.AddScoped<IOrderService, OrderApiClient>()).

var app = builder.Build();
if (!app.Environment.IsDevelopment()) { app.UseExceptionHandler("/Error", createScopeForErrors: true); app.UseHsts(); }
app.UseHttpsRedirection();
app.UseStaticFiles();
app.UseAntiforgery();
app.MapRazorComponents<App>().AddInteractiveServerRenderMode();
app.Run();
`);
  add(`${W}appsettings.json`, `{\n  "ApiBaseUrl": "https://localhost:7001",\n  "Logging": { "LogLevel": { "Default": "Information", "Microsoft.AspNetCore": "Warning" } },\n  "AllowedHosts": "*"\n}\n`);
  add(`${W}_Imports.razor`, [
    'System.Net.Http', 'System.Net.Http.Json', 'Microsoft.AspNetCore.Authorization',
    'Microsoft.AspNetCore.Components.Forms', 'Microsoft.AspNetCore.Components.Routing',
    'Microsoft.AspNetCore.Components.Web', 'static Microsoft.AspNetCore.Components.Web.RenderMode',
    'Microsoft.JSInterop', `${proj}.Web`, `${proj}.Web.Components`, `${proj}.Web.Components.Layout`,
    ...[...ns].sort()
  ].map(u => `@using ${u}`).join('\n') + '\n');
  add(`${W}Components/App.razor`, `<!DOCTYPE html>
<html lang="en">
<head>
    <meta charset="utf-8" />
    <meta name="viewport" content="width=device-width, initial-scale=1.0" />
    <base href="/" />
    <link rel="preconnect" href="https://fonts.googleapis.com" />
    <link href="https://fonts.googleapis.com/css2?family=Inter:wght@400;500;600&family=Plus+Jakarta+Sans:wght@600;700;800&display=swap" rel="stylesheet" />
    <script src="https://cdn.tailwindcss.com/3.4.17"></script>
    <script src="js/tailwind.config.js"></script>
    <link rel="stylesheet" href="css/app.css" />
    <HeadOutlet @rendermode="InteractiveServer" />
</head>
<body class="bg-slate-50 font-[Inter] text-slate-900">
    <Routes @rendermode="InteractiveServer" />
    <script src="_framework/blazor.web.js"></script>
    <script src="https://cdn.jsdelivr.net/npm/lucide@0.469.0/dist/umd/lucide.min.js"></script>
</body>
</html>
`);
  add(`${W}Components/Routes.razor`, `<Router AppAssembly="typeof(Program).Assembly">
    <Found Context="routeData">
        <RouteView RouteData="routeData" DefaultLayout="typeof(Layout.MainLayout)" />
        <FocusOnNavigate RouteData="routeData" Selector="h1" />
    </Found>
    <NotFound>
        <LayoutView Layout="typeof(Layout.MainLayout)"><h1 class="text-2xl font-bold">Page not found</h1></LayoutView>
    </NotFound>
</Router>
`);
  // nav links from the pages' @page routes
  const pages = tree.filter(t => rel(t).startsWith(W) && rel(t).endsWith('.razor'))
    .map(t => ({ route: (String(t.content).match(/^@page\s+"([^"]+)"/m) || [])[1], name: rel(t).split('/').pop().replace('.razor', '') }))
    .filter(p => p.route && !p.route.includes('{'));
  const links = pages.map(p => `            <NavLink href="${p.route.replace(/^\//, '')}" class="rounded-lg px-3 py-2 text-slate-600 hover:text-slate-900" ActiveClass="text-indigo-600 font-semibold"${p.route === '/' ? ' Match="NavLinkMatch.All"' : ''}>${p.name.replace(/([a-z])([A-Z])/g, '$1 $2')}</NavLink>`).join('\n');
  add(`${W}Components/Layout/MainLayout.razor`, `@inherits LayoutComponentBase
<div class="min-h-screen">
    <header class="sticky top-0 z-40 border-b border-slate-200 bg-white/80 backdrop-blur">
        <nav class="mx-auto flex max-w-6xl flex-wrap items-center gap-2 px-4 py-3">
            <a href="" class="mr-4 font-[Plus_Jakarta_Sans] text-lg font-extrabold">${proj}</a>
${links}
        </nav>
    </header>
    <main class="mx-auto max-w-6xl px-4 py-8">@Body</main>
</div>
`);
  add(`${W}wwwroot/css/app.css`, `h1:focus { outline: none; }\nsvg.lucide { width: 1.25em; height: 1.25em; stroke-width: 1.75; }\n`);
  add(`${W}wwwroot/js/tailwind.config.js`, `tailwind.config = { theme: { extend: { fontFamily: { display: ['"Plus Jakarta Sans"', 'system-ui', 'sans-serif'], body: ['Inter', 'system-ui', 'sans-serif'] } } } };\n`);
  add(`${W}Properties/launchSettings.json`, `{\n  "profiles": {\n    "https": { "commandName": "Project", "launchBrowser": true, "applicationUrl": "https://localhost:7002;http://localhost:5002", "environmentVariables": { "ASPNETCORE_ENVIRONMENT": "Development" } }\n  }\n}\n`);

  // --- root files ---
  add('global.json', `{\n  "sdk": { "version": "8.0.100", "rollForward": "latestMajor" }\n}\n`);
  add('.gitignore', `bin/\nobj/\n.vs/\n*.user\nappsettings.*.local.json\n.env\n`);

  // --- solution: always rebuilt from the .csproj files that really exist ---
  tree.splice(0, tree.length, ...tree.filter(t => !(rel(t).endsWith('.sln') && !rel(t).includes('/'))));
  const csprojs = tree.map(rel).filter(p => p.endsWith('.csproj')).sort();
  const g = (a, i) => `{8F3A1C2B-${a}-4A00-9000-${String(i).padStart(12, '0')}}`;
  const C = '{FAE04EC0-301F-11D3-BF4B-00C04F79EFBC}', F = '{2150E333-8FDC-42A3-9474-1A3956D46DE8}';
  let s = 'Microsoft Visual Studio Solution File, Format Version 12.00\r\n# Visual Studio Version 17\r\nVisualStudioVersion = 17.0.31903.59\r\nMinimumVisualStudioVersion = 10.0.40219.1\r\n';
  s += `Project("${F}") = "src", "src", "${g('1111', 1)}"\r\nEndProject\r\nProject("${F}") = "tests", "tests", "${g('1111', 2)}"\r\nEndProject\r\n`;
  csprojs.forEach((p, i) => { s += `Project("${C}") = "${p.split('/').pop().replace('.csproj', '')}", "${p.replace(/\//g, '\\')}", "${g('2222', i + 1)}"\r\nEndProject\r\n`; });
  s += 'Global\r\n\tGlobalSection(SolutionConfigurationPlatforms) = preSolution\r\n\t\tDebug|Any CPU = Debug|Any CPU\r\n\t\tRelease|Any CPU = Release|Any CPU\r\n\tEndGlobalSection\r\n\tGlobalSection(ProjectConfigurationPlatforms) = postSolution\r\n';
  csprojs.forEach((p, i) => { const id = g('2222', i + 1); ['Debug', 'Release'].forEach(c => { s += `\t\t${id}.${c}|Any CPU.ActiveCfg = ${c}|Any CPU\r\n\t\t${id}.${c}|Any CPU.Build.0 = ${c}|Any CPU\r\n`; }); });
  s += '\tEndGlobalSection\r\n\tGlobalSection(NestedProjects) = preSolution\r\n';
  csprojs.forEach((p, i) => { s += `\t\t${g('2222', i + 1)} = ${p.startsWith('tests/') ? g('1111', 2) : g('1111', 1)}\r\n`; });
  s += '\tEndGlobalSection\r\nEndGlobal\r\n';
  put(`${proj}.sln`, s);
}
dotnetSafetyNet(tree, root);
// ---- end .NET safety net ----

if (!tree.length) throw new Error('No files were generated');
const paths = tree.map(t => t.path);
const idx = paths.find(p => /\/site\/index\.html$/.test(p)) || paths.find(p => p.endsWith('/index.html'));
return [{ json: {
  root, tree,
  message: `AI build: ${form['Project Name']}`,
  siteUrl: idx ? 'https://meghana-m-revankar.github.io/ai-builder/' + idx.replace(/index\.html$/, '') : '',
  repoUrl: `https://github.com/meghana-m-revankar/ai-builder/tree/main/projects/${root}`
}}];
